 const met=all.filter(x=>ev.has(x[0])).length;
 const completion=all.length?Math.round(met/all.length*100):0;
 const totalOTJ=hours.reduce((n,x)=>n+Number(x.n||0),0);
 const meta=courseProgressMeta();
